def changes_possible(input_grid):
    """Check if an 8 can reach any diagonal 6 by moving through non-8 cells."""
    rows = len(input_grid)
    cols = len(input_grid[0])
    diagonal_6s = set()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 6:
                diagonal_6s.add((r, c))

    changed_positions = set()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 8:
                # Can we reach any diagonal 6 from here?
                # Directions: (dr, dc) where |dr| == |dc| and not both 0
                can_reach = False
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < rows and 0 <= nc < cols:
                        if input_grid[nr][nc] == 6:
                            can_reach = True
                            break
                        elif input_grid[nr][nc] == 8:
                            # blocked
                            break
                        else:
                            # non-8, continue
                            nr = nr + dr
                            nc = nc + dc

                if can_reach:
                    changed_positions.add((r, c))

    # Mark all cells that will change (8s that can reach a 6)
    modified_grid = [row[:] for row in input_grid]
    for r, c in sorted(changed_positions, reverse=True):
        if modified_grid[r][c] == 8:
            modified_grid[r][c] = 3

    return modified_grid

