# Calculate distance to nearest 6 (Chebyshev distance = max of row diff, col diff)
def chebyshev_dist(grid, r, c):
    min_dist = float('inf')
    for rr in range(len(grid)):
        for cc in range(len(grid[0])):
            if grid[rr][cc] == 6:
                dist = max(abs(rr - r), abs(cc - c))
                min_dist = min(min_dist, dist)
    return min_dist

